def attach_authors(posts, users):
    """Return the posts, each with an "author" key: the user whose "id" equals the post's "author_id", or None."""
    result = []
    for post in posts:
        author = None
        for user in users:
            if user["id"] == post["author_id"]:
                author = user
                break
        result.append({**post, "author": author})
    return result

