class Meter:
    """How much id work the code under test has done, and the most it is allowed (None: no limit)."""
    count = 0
    limit = None

    @classmethod
    def tick(cls):
        cls.count += 1
        if cls.limit is not None and cls.count > cls.limit:
            raise AssertionError(f"{cls.count:,} id comparisons and hashes and still going: looking up every post's author by scanning the users is O(posts x users) (n+1 style). Look the author up directly instead")
class Uid(int):
    """A user id that counts every equality test and every hash it takes part in."""
    def __eq__(self, other):
        Meter.tick()
        return int.__eq__(self, other)

    def __ne__(self, other):
        Meter.tick()
        return int.__ne__(self, other)

    def __hash__(self):
        Meter.tick()
        return int.__hash__(self)
def feed_scales(n_users, n_posts):
    """Run attach_authors on a big feed with the id work metered; check the answer too."""
    users = [{"id": Uid(i), "name": f"user{i}"} for i in range(n_users)]
    posts = [{"id": i, "author_id": Uid((i * 7919) % n_users if i % 10 else n_users + 5)} for i in range(n_posts)]
    Meter.count, Meter.limit = 0, 8 * (n_users + n_posts)
    try:
        feed = attach_authors(posts, users)
    finally:
        Meter.limit = None
    if len(feed) != n_posts:
        raise AssertionError(f"expected {n_posts} posts back, got {len(feed)}")
    for post, entry in zip(posts, feed):
        author_id = int(post["author_id"])
        want = users[author_id] if author_id < n_users else None
        if entry["id"] != post["id"] or entry["author"] != want:
            raise AssertionError(f"post {post['id']}: expected author {want!r}, got {entry['author']!r}")
    return True
